paradigm.source:
.card {
  @ds-surface(contained);
  display: grid;
  padding: density(4);
  gap: xs(0.5rem) md(1rem);
}
.card h2 { @ds-typo(h2); }

paradigm.output:
:root { --uxdsl__typography__h2-font-size: var(--uxdsl__space__6); }
@media (min-width: 480px) { :root { --uxdsl__typography__h2-font-size: var(--uxdsl__space__7); } }
@media (min-width: 1024px) { :root { --uxdsl__typography__h2-font-size: var(--uxdsl__space__8); } }
@media (min-width: 1280px) { :root { --uxdsl__typography__h2-font-size: var(--uxdsl__space__9); } }
:root { --uxdsl__density__4: var(--uxdsl__space__4); }
@media (min-width: 768px) { :root { --uxdsl__density__4: var(--uxdsl__space__5); } }
@media (min-width: 1280px) { :root { --uxdsl__density__4: var(--uxdsl__space__6); } }
.card {
  padding: var(--uxdsl__surface__contained-padding);
  border-radius: var(--uxdsl__surface__contained-radius);
  background: var(--uxdsl__surface__contained-bg);
  color: var(--uxdsl__surface__contained-color);
  border: var(--uxdsl__surface__contained-border);
  box-shadow: var(--uxdsl__surface__contained-shadow);
  display: grid;
  padding: var(--uxdsl__density__4);
  gap: 0.5rem;
}
@media (min-width: 768px) { .card { gap: 1rem; } }
.card h2 {
  font-family: var(--uxdsl__typography__h2-font-family);
  font-size: var(--uxdsl__typography__h2-font-size);
  line-height: var(--uxdsl__typography__h2-line-height);
  font-weight: var(--uxdsl__typography__h2-font-weight);
  letter-spacing: var(--uxdsl__typography__h2-letter-spacing);
  margin-block-start: var(--uxdsl__typography__h2-margin-block-start);
  margin-block-end: var(--uxdsl__typography__h2-margin-block-end);
}

quick-start.output:
:root { --uxdsl__density__3: var(--uxdsl__space__3); }
@media (min-width: 768px) { :root { --uxdsl__density__3: var(--uxdsl__space__4); } }
@media (min-width: 1280px) { :root { --uxdsl__density__3: var(--uxdsl__space__5); } }
.example {
  padding: var(--uxdsl__surface__contained-padding);
  border-radius: var(--uxdsl__surface__contained-radius);
  background: var(--uxdsl__surface__contained-bg);
  color: var(--uxdsl__surface__contained-color);
  border: var(--uxdsl__surface__contained-border);
  box-shadow: var(--uxdsl__surface__contained-shadow);
  padding: var(--uxdsl__density__3);
}

breakpoints.source:
.layout {
  display: flex;
  flex-direction: xs(column) md(row);
  gap: density(3);
}

breakpoints.output:
:root { --uxdsl__density__3: var(--uxdsl__space__3); }
@media (min-width: 800px) { :root { --uxdsl__density__3: var(--uxdsl__space__4); } }
@media (min-width: 1280px) { :root { --uxdsl__density__3: var(--uxdsl__space__5); } }
.layout {
  display: flex;
  flex-direction: column;
  gap: var(--uxdsl__density__3);
}
@media (min-width: 800px) { .layout { flex-direction: row; } }

spacing.output:
:root {
  --uxdsl__space__4: 0.75rem;
  --uxdsl__space__5: 1rem;
  --uxdsl__space__6: 1.5rem;
}
:root { --uxdsl__density__4: var(--uxdsl__space__4); }
@media (min-width: 768px) { :root { --uxdsl__density__4: var(--uxdsl__space__5); } }
@media (min-width: 1280px) { :root { --uxdsl__density__4: var(--uxdsl__space__6); } }
.card { padding: var(--uxdsl__density__4); }
.toolbar { gap: var(--uxdsl__space__4); }

colors.source:
.cta {
  background: palette(primary.main);
  color: palette(primary.contrast);
}
.swatch { background: color(blue.700); }
.scrim { background: color(black, 0.5); }

colors.output:
:root {
  --uxdsl__palette__primary-main: var(--uxdsl__color__blue-700);
  --uxdsl__palette__primary-contrast: var(--uxdsl__color__white);
  --uxdsl__color__blue-500: #3b82f6;
  --uxdsl__color__blue-700: #1d4ed8;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) {
    --uxdsl__palette__primary-main: var(--uxdsl__color__blue-500);
    --uxdsl__palette__primary-contrast: var(--uxdsl__color__black);
  }
}
:root[data-theme='dark'] {
  --uxdsl__palette__primary-main: var(--uxdsl__color__blue-500);
  --uxdsl__palette__primary-contrast: var(--uxdsl__color__black);
}
.cta {
  background: var(--uxdsl__palette__primary-main);
  color: var(--uxdsl__palette__primary-contrast);
}
.swatch { background: var(--uxdsl__color__blue-700); }
.scrim { background: color-mix(in srgb, var(--uxdsl__color__black) 50%, transparent); }

typography.output:
:root {
  --uxdsl__typography__h2-font-size: var(--uxdsl__space__6);
  --uxdsl__typography__h2-line-height: 1.25;
}
@media (min-width: 768px) {
  :root {
    --uxdsl__typography__h2-font-size: var(--uxdsl__space__7);
    --uxdsl__typography__h2-line-height: 1.3;
  }
}
@media (min-width: 1280px) { :root { --uxdsl__typography__h2-font-size: var(--uxdsl__space__9); } }
.section-title {
  font-family: var(--uxdsl__typography__h2-font-family);
  font-size: var(--uxdsl__typography__h2-font-size);
  line-height: var(--uxdsl__typography__h2-line-height);
  font-weight: var(--uxdsl__typography__h2-font-weight);
  letter-spacing: var(--uxdsl__typography__h2-letter-spacing);
  margin-block-start: var(--uxdsl__typography__h2-margin-block-start);
  margin-block-end: var(--uxdsl__typography__h2-margin-block-end);
}

borders.theme:
{
  "borders": {
    "1": "xs(1px solid palette(divider.main)) md(2px solid palette(divider.main))"
  },
  "radii": {
    "2": "xs(space(2)) md(space(3))"
  }
}

borders.source:
.card {
  border: border(1);
  border-radius: radius(2);
}
.chip { border-radius: radius(pill); }
.avatar { border-radius: radius(circle); }

borders.output:
:root {
  --uxdsl__border__1: 1px solid var(--uxdsl__palette__divider-main);
  --uxdsl__radius__2: var(--uxdsl__space__2);
}
@media (min-width: 768px) {
  :root {
    --uxdsl__border__1: 2px solid var(--uxdsl__palette__divider-main);
    --uxdsl__radius__2: var(--uxdsl__space__3);
  }
}
.card {
  border: var(--uxdsl__border__1);
  border-radius: var(--uxdsl__radius__2);
}
.chip { border-radius: 9999px; }
.avatar { border-radius: 50%; }

shadows.output:
:root {
  --uxdsl__shadow__0: none;
  --uxdsl__shadow__2: 0 1px 2px rgba(0, 0, 0, 0.12);
}
@media (min-width: 768px) { :root { --uxdsl__shadow__2: 0 4px 12px rgba(0, 0, 0, 0.16); } }
.card { box-shadow: var(--uxdsl__shadow__2); }
.flat { box-shadow: var(--uxdsl__shadow__0); }

surfaces.output:
:root { --uxdsl__surface__contained-shadow: var(--uxdsl__shadow__1); }
@media (min-width: 768px) {
  :root { --uxdsl__surface__contained-shadow: var(--uxdsl__shadow__3); }
}
.card {
  padding: var(--uxdsl__surface__contained-padding);
  border-radius: var(--uxdsl__surface__contained-radius);
  background: var(--uxdsl__surface__contained-bg);
  color: var(--uxdsl__surface__contained-color);
  border: var(--uxdsl__surface__contained-border);
  box-shadow: var(--uxdsl__surface__contained-shadow);
}
.notice {
  padding: var(--uxdsl__density__2);
  border-radius: var(--uxdsl__radius__2);
  background: transparent;
  color: var(--uxdsl__palette__info-main);
  border: 1px solid var(--uxdsl__palette__info-main);
  box-shadow: var(--uxdsl__surface__outlined-shadow);
}

buttons.output:
:root {
  --uxdsl__button__checkout-base-padding: var(--uxdsl__density__3);
  --uxdsl__button__checkout-hover-bg: var(--uxdsl__button__tone-dark, var(--uxdsl__palette__primary-dark));
}
.checkout {
  padding: var(--uxdsl__button__checkout-base-padding);
  border-radius: var(--uxdsl__surface__contained-radius);
  background: var(--uxdsl__surface__contained-bg);
  color: var(--uxdsl__surface__contained-color);
  border: var(--uxdsl__surface__contained-border);
  box-shadow: var(--uxdsl__surface__contained-shadow);
}
.checkout:hover:not(:where(:disabled, [aria-disabled="true"])) {
  background: var(--uxdsl__button__checkout-hover-bg);
  color: var(--uxdsl__button__checkout-hover-color);
}
.checkout:focus-visible {
  outline: var(--uxdsl__button__checkout-focusvisible-outline);
  outline-offset: var(--uxdsl__button__checkout-focusvisible-outline-offset);
}
.checkout.is-selected, .checkout[aria-pressed="true"], .checkout[aria-selected="true"] {
  background: var(--uxdsl__button__checkout-selected-bg);
  color: var(--uxdsl__button__checkout-selected-color);
}
.checkout:disabled, .checkout[aria-disabled="true"] {
  opacity: var(--uxdsl__button__checkout-disabled-opacity);
  cursor: var(--uxdsl__button__checkout-disabled-cursor);
}

inputs.output:
:root {
  --uxdsl__input__search-base-placeholder: var(--uxdsl__palette__neutral-dark);
  --uxdsl__input__search-invalid-border: 2px solid var(--uxdsl__palette__error-main);
}
.search {
  box-sizing: border-box;
  font: inherit;
  width: 100%;
  padding: var(--uxdsl__surface__outlined-padding);
  border-radius: var(--uxdsl__surface__outlined-radius);
  background: var(--uxdsl__surface__outlined-bg);
  color: var(--uxdsl__surface__outlined-color);
  border: var(--uxdsl__surface__outlined-border);
  box-shadow: var(--uxdsl__surface__outlined-shadow);
  caret-color: var(--uxdsl__input__search-base-caret);
}
.search::placeholder { color: var(--uxdsl__input__search-base-placeholder); }
.search:focus {
  border: var(--uxdsl__input__search-focus-border);
  box-shadow: var(--uxdsl__input__search-focus-shadow);
}
.search:invalid, .search[aria-invalid="true"] { border: var(--uxdsl__input__search-invalid-border); }
.search:disabled, .search[aria-disabled="true"] {
  color: var(--uxdsl__input__search-disabled-color);
  opacity: var(--uxdsl__input__search-disabled-opacity);
  cursor: var(--uxdsl__input__search-disabled-cursor);
}
